async def flush_pending_delta_data(threshold: int = 0):
    nonlocal delta_count
    nonlocal last_delta_data

    if delta_count >= threshold and last_delta_data:
        await event_emitter(
            {
                "type": "chat:completion",
                "data": last_delta_data,
            }
        )
        delta_count = 0
        last_delta_data = None

